userrole.from_stored.code:
pub fn from_stored(raw: &[u8]) -> Option<UserRole> {
    if equal(raw, b"owner") {
        Some(UserRole::Owner)
    } else if equal(raw, b"admin") {
        Some(UserRole::Admin)
    } else if equal(raw, b"user") {
        Some(UserRole::User)
    } else {
        None
    }
}

