    match role {
        UserRole::Anonymous => true,
        _ => false,
    }
}

userrole.is_privileged.code:
pub fn is_privileged(role: UserRole) -> bool {
    rank(role) > rank(UserRole::User)
}

userrole.str_at_least.code:
