        Strictness::TrueIsStricter=>{let a=knob_bool(p,knob);let b=knob_bool(other,knob);a || !b},
        Strictness::FalseIsStricter=>{let a=knob_bool(p,knob);let b=knob_bool(other,knob);!a || b},
