/// `frontend/src/lib/utils/drivePolicies.ts`.
pub const POLICY_KNOBS: &[&str] = &[
    "forbid_sharing",
    "forbid_external_sharing",
    "forbid_public_links",
    "forbid_cross_drive_move",
    "forbid_owner_role_change",
    "include_in_photo_index",
